class Solution {
    public void rotate(int[] nums, int k) {
        int length = nums.length;
        k %= length;
        int[] rotated = new int[length];
        for (int index = 0; index < length; index++) {
            rotated[(index + k) % length] = nums[index];
        }
        System.arraycopy(rotated, 0, nums, 0, length);
    }
}

